svg.script:
(function(){
  const svg=document.documentElement;
  const meta=JSON.parse(document.getElementById('pbn-meta').textContent);
  const labels=document.getElementById('number-labels');
  const legend=document.getElementById('legend');
  const NS='http://www.w3.org/2000/svg';
  const make=(tag,at,text)=>{const e=document.createElementNS(NS,tag);Object.entries(at||{}).forEach(([k,v])=>e.setAttribute(k,v));if(text!=null)e.textContent=text;return e};
  const regions=[...document.querySelectorAll('.region')];
  const cols=4,cellW=205,cellH=40,startX=40,startY=950;
  const rows=Math.ceil(meta.palette.length/cols),buttonY=startY+rows*cellH+12;
  const legendHeight=(buttonY-900)+56,viewHeight=900+legendHeight+15;
  let numbersVisible=true;

  function paintedNodes(el){
    if(el.dataset.paintChildren==='1') return [el,...el.querySelectorAll('path,rect,circle,ellipse,polygon,polyline')];
    return [el];
  }
  function apply(el,painted){
    const color=el.dataset.suggested;
    const mode=el.dataset.paintMode||'fill';
    el.dataset.painted=painted?'1':'0';
    paintedNodes(el).forEach(node=>{
      if(mode==='stroke'){
        node.style.fill='none';
        node.style.stroke=painted?color:'#91877c';
      }else{
        node.style.fill=painted?color:'#fffdf8';
      }
    });
    const label=document.querySelector('[data-label-for="'+el.id+'"]');
    if(label) label.setAttribute('display',painted?'none':(numbersVisible?'inline':'none'));
  }
  function resetRegion(el){apply(el,false)}

  regions.forEach((el,index)=>{
    if(!el.id)el.id='region-'+String(index+1).padStart(3,'0');
    const n=Number(el.dataset.color);
    const color=el.dataset.suggested||meta.palette[n-1]?.hex||'#d8cfc3';
    el.dataset.suggested=color;
    el.dataset.painted='0';
    el.setAttribute('tabindex','0');
    el.setAttribute('role','button');
    el.setAttribute('aria-label','Paint region '+(index+1)+', color '+n);
    resetRegion(el);
    let box,inv;try{box=el.getBoundingClientRect();inv=labels.getScreenCTM().inverse()}catch(_){return}
    const p1=svg.createSVGPoint(),p2=svg.createSVGPoint();p1.x=box.left;p1.y=box.top;p2.x=box.right;p2.y=box.bottom;
    const a=p1.matrixTransform(inv),b=p2.matrixTransform(inv),w=Math.abs(b.x-a.x),h=Math.abs(b.y-a.y),area=w*h;
    if(w>=20&&h>=16&&area>=360){
      const fs=Math.max(8,Math.min(22,Math.sqrt(area)/7));
      const t=make('text',{
        x:((a.x+b.x)/2).toFixed(1),
        y:((a.y+b.y)/2+fs*.34).toFixed(1),
        'text-anchor':'middle',
        'font-size':fs.toFixed(1),
        class:'pbn-number',
        'data-label-for':el.id
      },String(n));
      labels.appendChild(t);
    }
    const run=ev=>{apply(el,!ev.shiftKey)};
    el.addEventListener('click',run);
    el.addEventListener('keydown',ev=>{if(ev.key==='Enter'||ev.key===' '){ev.preventDefault();run(ev)}});
  });

  svg.setAttribute('viewBox',`0 0 900 ${viewHeight}`);
  svg.setAttribute('height',String(viewHeight));
  legend.setAttribute('display','inline');
  const bg=document.getElementById('legend-bg');if(bg)bg.setAttribute('height',String(legendHeight));
  meta.palette.forEach((p,i)=>{
    const col=i%cols,row=Math.floor(i/cols),x=startX+col*cellW,y=startY+row*cellH;
    legend.appendChild(make('rect',{x,y,width:34,height:28,rx:5,fill:p.hex,class:'legend-swatch'}));
    legend.appendChild(make('text',{x:x+43,y:y+20,'font-size':15,'font-weight':700,class:'legend-label'},`${i+1}. ${p.name}`));
  });
  const button=(x,label,fn)=>{
    const g=make('g',{class:'control',tabindex:0,role:'button','aria-label':label});
    g.appendChild(make('rect',{x,y:buttonY,width:160,height:38,rx:12,fill:'#fffaf1',stroke:'#6f5a43','stroke-width':2}));
    g.appendChild(make('text',{x:x+80,y:buttonY+25,'text-anchor':'middle','font-size':16,'font-weight':800,class:'legend-label'},label));
    const run=()=>fn();g.addEventListener('click',run);g.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();run()}});legend.appendChild(g);
  };
  button(160,'Fill all',()=>regions.forEach(el=>apply(el,true)));
  button(370,'Reset',()=>regions.forEach(resetRegion));
  button(580,'Toggle numbers',()=>{numbersVisible=!numbersVisible;labels.setAttribute('display',numbersVisible?'inline':'none')});
})();
